function replaceWordsWithSynonyms(passage) {
  const synonyms = {
    "establishment": "institution",
    "commended": "applauded",
    "numerous": "multitudinous",
    "accolades": "plaudits",
    "preeminent": "supreme",
    "carnivorous": "meat-eating",
    "cuisine": "food",
    "exalted": "revered",
    "appraisal": "evaluation",
    "fine dining": "gourmet dining"
  };
  // Split the passage into an array of words
  const words = passage.split(" ");
  // Iterate through each word and replace it with its synonym if it exists
  const replacedWords = words.map((word) => {
    const lowerCaseWord = word.toLowerCase().replace(/[^\w\s]/gi, "");
    if (synonyms[lowerCaseWord]) {
      return synonyms[lowerCaseWord];
    } else {
      return word;
    }
  });
  // Join the replaced words back into a passage
  const replacedPassage = replacedWords.join(" ");
  return replacedPassage;
}
```
