Program 2: Apache Lucene
Apache Lucene is a high-performance, full-featured text search engine library written in Java. It provides powerful indexing and searching capabilities for text-based documents. Here is an example of how to use Apache Lucene to create an index of a set of documents and search for a specific term:
```
import org.apache.lucene.analysis.standard.StandardAnalyzer;
import org.apache.lucene.document.Document;
import org.apache.lucene.document.Field;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.index.Term;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.search.TermQuery;
import org.apache.lucene.store.Directory;
import org.apache.lucene.store.FSDirectory;
import java.nio.file.Paths;
public class SearchEngine {
  public static void main(String[] args) throws Exception {
    // Create an index writer
    Directory indexDirectory = FSDirectory.open(Paths.get("index"));
    IndexWriterConfig config = new IndexWriterConfig(new StandardAnalyzer());
    IndexWriter writer = new IndexWriter(indexDirectory, config);
    // Add some documents to the index
    Document doc1 = new Document();
    doc1.add(new Field("title", "The quick brown fox", Field.Store.YES, Field.Index.ANALYZED));
    doc1.add(new Field("content", "Jumped over the lazy dog", Field.Store.YES, Field.Index.ANALYZED));
    writer.addDocument(doc1);
    Document doc2 = new Document();
    doc2.add(new Field("title", "Lorem ipsum dolor sit amet", Field.Store.YES, Field.Index.ANALYZED));
    doc2.add(new Field("content", "Consectetur adipiscing elit", Field.Store.YES, Field.Index.ANALYZED));
    writer.addDocument(doc2);
    writer.close();
    // Search for a term in the index
    DirectoryReader reader = DirectoryReader.open(indexDirectory);
    IndexSearcher searcher = new IndexSearcher(reader);
    Query query = new TermQuery(new Term("content", "lazy"));
    ScoreDoc[] hits = searcher.search(query, 10).scoreDocs;
    // Print out the results
    for (ScoreDoc hit : hits) {
      Document doc = searcher.doc(hit.doc);
      System.out.println(doc.get("title"));
    }
    reader.close();
  }
}
```

