import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
public class Country {
    private String name;
    private int population;
    public Country(String name, int population) {
        this.name = name;
        this.population = population;
    }
    public String getName() {
        return name;
    }
    public int getPopulation() {
        return population;
    }
    public static void main(String[] args) {
        List<Country> countries = new ArrayList<>();
        countries.add(new Country("Canada", 38008005));
        countries.add(new Country("Mexico", 130222815));
        countries.add(new Country("Brazil", 211714080));
        Collections.sort(countries, new Comparator<Country>() {
            @Override
            public int compare(Country c1, Country c2) {
                return c1.getPopulation() - c2.getPopulation();
            }
        });
        for (Country country : countries) {
            System.out.println(country.getName() + " - " + country.getPopulation());
        }
    }
}
