Here is a sample code:
string word = "dowager";
char[] letters = word.ToCharArray();
Array.Sort(letters);
string sortedWord = new string(letters);
Console.WriteLine("Sorted letters: " + sortedWord);
// Create list of all permutations
List<string> permutations = new List<string>();
Permute("", sortedWord, permutations);
// Filter list to only include 5 letter words
List<string> fiveLetterWords = permutations.FindAll(w => w.Length == 5);
// Print the list of five letter words
Console.WriteLine("Five letter words: ");
foreach (string word in fiveLetterWords)
{
    Console.WriteLine(word);
}
// Method to find all permutations of a string
private static void Permute(string prefix, string suffix, List<string> permutations)
{
    int n = suffix.Length;
    if (n == 0) permutations.Add(prefix);
    else
    {
        for (int i = 0; i < n; i++)
            Permute(prefix + suffix[i], suffix.Substring(0, i) + suffix.Substring(i + 1), permutations);
    }
}

